DROP TABLE IF EXISTS t_ponflowanalyse_14 CASCADE;

CREATE TABLE t_ponflowanalyse_14 (
   cneid int,
   cobjectid int,
   cportno int,
   ctype int,
   cstattime timestamp,
   cpmtype int,
   cmaxvalue decimal(19, 4),
   cmaxoccurtime timestamp,
   cminvalue decimal(19, 4),
   cminoccurtime timestamp,
   caveragevalue decimal(19, 4),
   ccollectcount int,
   cobjectname char(255),
   creservedint int,
   creserved char(32)
)
tablespace unmdb_space
distributed by (cneid)
;


CREATE INDEX ix_max_pmvalue_14 ON t_ponflowanalyse_14 (
cmaxvalue DESC
);


CREATE INDEX ix_query_index_14 ON t_ponflowanalyse_14 (
cstattime ASC,cobjectid ASC,cportno ASC,cpmtype ASC
);


CREATE INDEX ix_topn_query_14 ON t_ponflowanalyse_14 (
cstattime ASC,cneid ASC,ctype ASC,cpmtype ASC
);

